/* 后续安排是原任务的子对象；HTML固定，命令仍由保养接口处理。 */
window.EamMaintenanceFollowupUi=(()=>{let task,changed,dirty,busy=false,initialized=false;const $=id=>document.getElementById(id),states={pending:'待处理',pending_review:'待独立复核',completed:'已完成'};
return {bind(t,config,onChanged,isDirty){task=t;changed=onChanged;dirty=isDirty;const panel=$('mf-panel');if(!panel)return;panel.hidden=!t.followup;if(!t.followup)return;const f=t.followup;
 $('mf-state').textContent=states[f.status];$('mf-arrangement').textContent=f.arrangement;$('mf-owner').textContent=config.followupPeople.find(p=>p.id===f.ownerId)?.name||f.ownerId;$('mf-due').textContent=f.dueAt;$('mf-controls').textContent=f.risk+'；控制措施：'+f.controls;$('mf-result').textContent=[f.result,f.reviewReason].filter(Boolean).join('；')||'尚未提交结果';
 $('mf-form').hidden=!t.actions['submit-followup']&&!t.actions['review-followup'];$('mf-decision-field').hidden=!t.actions['review-followup'];$('mf-submit').textContent=t.actions['review-followup']?'提交独立复核':'提交后续处理结果';$('mf-form').reset();$('mf-error').textContent='';
 if(initialized)return;initialized=true;$('mf-form').onsubmit=async event=>{event.preventDefault();if(busy)return;if(dirty()){Eam.message('请先保存执行记录');return;}busy=true;$('mf-submit').disabled=true;try{const action=task.actions['review-followup']?'review-followup':'submit-followup',result=await EamMaintenanceApi.request('POST','/maintenance/tasks/'+encodeURIComponent(task.id)+'/'+action,{expectedRevision:task.revision,executionVersion:task.executionVersion,reason:$('mf-reason').value,evidence:$('mf-evidence').value,decision:$('mf-decision').value});changed(result);Eam.message('后续安排已更新；关联异常和设备限制仍由各自流程处置');}catch(e){$('mf-error').textContent=e.message+'；输入已保留';}finally{busy=false;$('mf-submit').disabled=false;}};
}};})();
